WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_d_midpoint'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '中间时点反求', 'kp-eng-d-midpoint', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "中间时点反求"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "在工程干到一半的某个中间时点给出一个新条件，倒推最开始的状态。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“工程进行到第 10 天时，刚好完成了总量的 1/3，此时……” 这种题目在时间轴上存在一个强锚点。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推论"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "中间时点是最大的宝藏！它直接告诉了你【前期的实际工作效率】。"}]}, {"type": "katexBlock", "attrs": {"content": "P_{实际前期} = \\frac{\\text{已完成的相对工作量}}{\\text{消耗的时间}}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[提取中间时点信息: T天内干了总量的 N/M] --> B[直接赋 W = M 份]\nB --> C[那么前 T 天就干了 N 份]\nC --> D[得出前期实际效率 = N / T]\nD --> E[再结合前期的人数或配置, 反推单个人的基准效率]\nE --> F[拿着基准效率去解后面的突变要求]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 某施工队修路，开工 8 天后，刚好修了全长的 1/4。之后为了加快进度，又调来了一样规模的队伍帮忙。问剩下还需要几天？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "利用中间时点定 W：修了 1/4，直接令总长度 W = 4 份。那么前 8 天修了 1 份。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算前期效率：原施工队的效率 P原 = 1份 ÷ 8天 = 1/8 份/天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算残局剩余：剩下 W余 = 4 - 1 = 3 份。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算突变后效率：调来一样规模的队伍，说明效率翻倍。P新 = (1/8) × 2 = 1/4 份/天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求新耗时：T新 = W余 ÷ P新 = 3 ÷ (1/4) = 12 天。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "死板追求整数效率：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "有时候算出 P = 1/8 是个分数，很多同学就不敢往下算了，非要把 W 设为 32。其实在这种阶段非常明确的题里，带着简单的分数往下走，最后做倒数乘法 (如除以 1/4 变成乘4) 也是极其快捷的。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "训练“半程结账”思维。看到“进行到一半”、“完成了三分之一”，立刻截断时间轴，把前面这段直接折算成一个固定的初始效率。"}]}]}$$ AS jsonb), NULL, '中间时点反求的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "中间时点反求"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_d_midpoint", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
